const original = ($('On called').first() && $('On called').first().json) || {};
const getCategoriesResult = ($input.first() && $input.first().json) || {};
const categories = getCategoriesResult.categories || [];

const description = (original.description || "").toLowerCase();

// BudgetFlow's CategoryType enum (INCOME/FIXED_EXPENSE/VARIABLE_EXPENSE/SAVINGS/DEBT/REMITTANCE)
// does not match TransactionType (INCOME/EXPENSE/SAVINGS/DEBT_PAYMENT/TRANSFER/REMITTANCE) 1:1.
const TYPE_MAP = {
  INCOME: ["INCOME"],
  EXPENSE: ["VARIABLE_EXPENSE", "FIXED_EXPENSE"],
  SAVINGS: ["SAVINGS"],
  DEBT_PAYMENT: ["DEBT"],
  REMITTANCE: ["REMITTANCE"],
  TRANSFER: ["VARIABLE_EXPENSE", "FIXED_EXPENSE"],
};
const wantTypes = TYPE_MAP[original.type] || ["VARIABLE_EXPENSE", "FIXED_EXPENSE"];

// EDIT ME: adjust keywords/category-name fragments to match your own categories.
const keywordMap = [
  { keywords: ["grocery", "groceries", "supermarket", "carrefour", "lulu", "spinneys", "market"], name: "groceries" },
  { keywords: ["restaurant", "cafe", "coffee", "starbucks", "dining", "food"], name: "dining" },
  { keywords: ["uber", "careem", "taxi", "fuel", "petrol", "parking", "transport"], name: "transport" },
  { keywords: ["electricity", "water", "dewa", "internet", "etisalat", "utility", "utilities"], name: "utilities" },
  { keywords: ["netflix", "spotify", "cinema", "movie", "entertainment"], name: "entertainment" },
  { keywords: ["pharmacy", "hospital", "clinic", "doctor", "health"], name: "health" },
  { keywords: ["salary", "payroll", "deposit", "income"], name: "salary" },
];

function findByKeyword() {
  for (const rule of keywordMap) {
    if (rule.keywords.some((kw) => description.includes(kw))) {
      const match = categories.find(
        (c) => wantTypes.includes(c.type) && c.name.toLowerCase().includes(rule.name)
      );
      if (match) return { category: match, confidence: 0.9 };
    }
  }
  return null;
}

let result = findByKeyword();

if (!result) {
  const uncategorized = categories.find(
    (c) => wantTypes.includes(c.type) && c.name.toLowerCase() === "uncategorized"
  );
  if (uncategorized) result = { category: uncategorized, confidence: 0.2 };
}

if (!result) {
  const fallback = categories.find((c) => wantTypes.includes(c.type));
  if (fallback) result = { category: fallback, confidence: 0.1 };
}

if (!result && categories.length > 0) {
  // Absolute last resort (e.g. TRANSFER with no matching category type): any category, very low confidence.
  result = { category: categories[0], confidence: 0.05 };
}

return [{
  json: {
    ...original,
    categoryId: result ? result.category.id : null,
    categoryName: result ? result.category.name : null,
    categorizeConfidence: result ? result.confidence : 0,
  },
}];
